def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    from collections import deque

    mod = 1_000_000_007
    children = [{}]
    fail = [0]
    terminal = [False]

    for word in banned:
        state = 0
        for char in word:
            if char not in children[state]:
                children[state][char] = len(children)
                children.append({})
                fail.append(0)
                terminal.append(False)
            state = children[state][char]
        terminal[state] = True

    queue = deque()
    for char in alphabet:
        if char in children[0]:
            queue.append(children[0][char])
        else:
            children[0][char] = 0

    while queue:
        state = queue.popleft()
        terminal[state] |= terminal[fail[state]]

        for char in alphabet:
            if char in children[state]:
                nxt = children[state][char]
                fail[nxt] = children[fail[state]][char]
                queue.append(nxt)
            else:
                children[state][char] = children[fail[state]][char]

    states = [state for state in range(len(children)) if not terminal[state]]
    index = {state: i for i, state in enumerate(states)}
    size = len(states)

    matrix = [[0] * size for _ in range(size)]
    for state in states:
        row = matrix[index[state]]
        for char in alphabet:
            nxt = children[state][char]
            if not terminal[nxt]:
                row[index[nxt]] += 1

    vector = [0] * size
    vector[index[0]] = 1

    while n:
        if n & 1:
            result = [0] * size
            for i, value in enumerate(vector):
                if value:
                    for j, weight in enumerate(matrix[i]):
                        result[j] += value * weight
            vector = [value % mod for value in result]

        n >>= 1
        if n:
            squared = [[0] * size for _ in range(size)]
            for i in range(size):
                for k, value in enumerate(matrix[i]):
                    if value:
                        for j, weight in enumerate(matrix[k]):
                            squared[i][j] += value * weight
                squared[i] = [value % mod for value in squared[i]]
            matrix = squared

    return sum(vector) % mod
